{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {"kind": "log", "sql": "SELECT regexp_extract(message, 'I/O error on (\\w+) request for \"([^\"]+)\"', 2) url, regexp_extract(message, 'nested exception is ([^;]+)', 1) cause, count(*) n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' GROUP BY ALL ORDER BY n DESC", "claim": "Preserve's outgoing POSTs to ts-seat-service/seats fail with 'Unexpected end of file' or 'Connection reset', about 1,495 of 1,497 I/O errors."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY ALL", "claim": "1,497 of 4,489 preserve POST client spans are Error, failing in about 1 ms with no child span."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name LIKE '%seats%' GROUP BY ALL", "claim": "Seat-service records no POST /seats server spans in the incident, only left_tickets, with zero errors; the seat-side spans are normal."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, round(sum(value),0) total FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND attr_source LIKE '%preserve-service%' GROUP BY ALL", "claim": "Preserve pod shows only 8 hubble drops in the incident, so the network link itself is not dropping packets."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%preserve%' GROUP BY ALL", "claim": "Ui-dashboard's POST /preserve server spans return 500 in 80 of 101 cases, median about 4.2 s, versus zero errors normally."}]}
  ]
}
